// One-shot FSM, asynchronous reset. The state machine itself has no path
// to the clock, so this is a purely combinational FSM with fast
// synchronous reset -> maximum frequency.
module TopModule(input clk, input reset, input data, input done_counting,
                 input ack, output reg shift_ena, output reg counting,
                 output reg done);
    reg [2:0] state, nextstate;
    reg [3:0] count;
    always @(*) begin
        case (state)
            3'd0: if (data) nextstate = 3'd1; else nextstate = 3'd0;
            3'd1: if (data) nextstate = 3'd2; else nextstate = 3'd0;
            3'd2: if (data) nextstate = 3'd3; else nextstate = 3'd0;
            3'd3: if (data) nextstate = 3'd4; else nextstate = 3'd0;
            3'd4: nextstate = 3'd5;
            3'd5: if (done_counting) nextstate = 3'd6; else nextstate = 3'd5;
            3'd6: if (ack) nextstate = 3'd0; else nextstate = 3'd6;
            default: nextstate = 3'd0;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin state <= 3'd0; shift_ena <= 1'b0; counting <= 1'b0; done <= 1'b0; count <= 4'd0; end
        else begin
            state <= nextstate;
            shift_ena <= (state == 3'd4);
            counting <= (state == 3'd5);
            done <= (state == 3'd6);
            if (state == 3'd4) count <= 4'd0;
            else if (state == 3'd5) count <= count + 4'd1;
        end
    end
endmodule

