// Finite-state machine: starts the timer when the sequence 1101 is
// detected, shifts in 4 more bits to determine the duration, waits for the
// counters to finish counting, and notifies the user (done = 1) and waits
// for the user to acknowledge the timer before starting again.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [2:0] state;
    reg [3:0] counter;
    reg [3:0] pattern;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
            counter <= 4'b0000;
            pattern <= 4'b1101;
        end else begin
            case (state)
                3'b000: begin // wait for the start sequence
                    if (data == pattern[3]) begin
                        state <= 3'b001;
                        shift_ena <= 1'b1;
                        counter <= 4'b0000;
                    end
                end
                3'b001: begin // shift in the next bit and go to state 2
                    if (counter == 4'b1111) begin
                        shift_ena <= 1'b0;
                        state <= 3'b010;
                        counter <= 4'b0000;
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b010: begin // wait for counters to finish
                    if (done_counting) begin
                        counting <= 1'b1;
                        state <= 3'b011;
                    end
                end
                3'b011: begin // wait for user to acknowledge the timer
                    if (ack) begin
                        done <= 1'b1;
                        counting <= 1'b0;
                        state <= 3'b000;
                    end
                end
            endcase
        end
    end
endmodule

