// One-bit timer that starts, waits, and resets exactly when a specific
// serial pattern (1101) is received. The duration to wait is determined
// by another 4 bits of serial input.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output reg shift_ena,
    output reg counting,
    output reg done
);
    reg [3:0] pattern;
    reg [3:0] delay;
    reg [2:0] state;
    always @(posedge clk) begin
        if (reset) begin
            pattern <= 4'b1101;
            delay <= 4'b0000;
            shift_ena <= 1'b0;
            counting <= 1'b0;
            done <= 1'b0;
            state <= 3'b001;
        end else begin
            case (state)
                3'b001: begin // wait for pattern
                    if (data == pattern[0]) begin
                        if (data == pattern[1] && data == pattern[2] && data == pattern[3]) begin
                            shift_ena <= 1'b1;
                            state <= 3'b010;
                        end
                    end else begin
                        pattern <= 4'b1101;
                    end
                end
                3'b010: begin // shift in 4 more bits to determine the duration to delay
                    delay[0] <= data;
                    state <= 3'b011;
                end
                3'b011: begin // shift in 3 more bits to determine the duration to delay
                    delay[1] <= data;
                    state <= 3'b100;
                end
                3'b100: begin // shift in 2 more bits to determine the duration to delay
                    delay[2] <= data;
                    state <= 3'b101;
                end
                3'b101: begin // shift in 1 more bit to determine the duration to delay
                    delay[3] <= data;
                    counting <= 1'b1;
                    state <= 3'b110;
                end
                3'b110: begin // wait for counters to finish counting
                    if (done_counting) begin
                        counting <= 1'b0;
                        done <= 1'b1;
                        state <= 3'b111;
                    end
                end
                3'b111: begin // wait for user to acknowledge the timer and reset
                    if (ack) begin
                        done <= 1'b0;
                        shift_ena <= 1'b0;
                        state <= 3'b001;
                    end
                end
            endcase
        end
    end
endmodule

